import { Kind } from 'graphql';
// Re-export Kind and OperationTypeNode for consumers
export { Kind, OperationTypeNode } from 'graphql';
export const document = ({ definitions }) => ({
    kind: Kind.DOCUMENT,
    definitions
});
export const operationDefinition = ({ operation, name, variableDefinitions = [], directives = [], selectionSet }) => ({
    kind: Kind.OPERATION_DEFINITION,
    operation,
    name: {
        kind: Kind.NAME,
        value: name
    },
    variableDefinitions,
    directives,
    selectionSet
});
export const variableDefinition = ({ variable, type, directives }) => ({
    kind: Kind.VARIABLE_DEFINITION,
    variable,
    type,
    directives: directives || []
});
export const selectionSet = ({ selections }) => ({
    kind: Kind.SELECTION_SET,
    selections
});
export const listType = ({ type }) => ({
    kind: Kind.LIST_TYPE,
    type
});
export const nonNullType = ({ type }) => ({
    kind: Kind.NON_NULL_TYPE,
    type
});
export const namedType = ({ type }) => ({
    kind: Kind.NAMED_TYPE,
    name: {
        kind: Kind.NAME,
        value: type
    }
});
export const variable = ({ name }) => ({
    kind: Kind.VARIABLE,
    name: {
        kind: Kind.NAME,
        value: name
    }
});
export const objectValue = ({ fields }) => ({
    kind: Kind.OBJECT,
    fields
});
export const stringValue = ({ value }) => ({
    kind: Kind.STRING,
    value
});
export const intValue = ({ value }) => ({
    kind: Kind.INT,
    value
});
export const booleanValue = ({ value }) => ({
    kind: Kind.BOOLEAN,
    value
});
export const floatValue = ({ value }) => ({
    kind: Kind.FLOAT,
    value
});
export const listValue = ({ values }) => ({
    kind: Kind.LIST,
    values
});
export const nullValue = () => ({
    kind: Kind.NULL
});
export const fragmentDefinition = ({ name, typeCondition, directives = [], selectionSet }) => ({
    kind: Kind.FRAGMENT_DEFINITION,
    name: {
        kind: Kind.NAME,
        value: name
    },
    typeCondition,
    directives,
    selectionSet
});
export const objectField = ({ name, value }) => ({
    kind: Kind.OBJECT_FIELD,
    name: {
        kind: Kind.NAME,
        value: name
    },
    value
});
export const field = ({ name, args = [], directives = [], selectionSet }) => ({
    kind: Kind.FIELD,
    name: {
        kind: Kind.NAME,
        value: name
    },
    arguments: args,
    directives,
    selectionSet
});
export const argument = ({ name, value }) => ({
    kind: Kind.ARGUMENT,
    name: {
        kind: Kind.NAME,
        value: name
    },
    value
});
